    /** 字符串在指定长度下进行左对齐，空出来的字符使用padChar补齐。如果传入多个字符将会取第一个字符。 */
    public static String alignLeft(String str, String padChar, int len) {
        if (str != null) {
            if (str.length() > len) {
                return str;
            }
        }
        char pad = padChar.length() == 0 ? ' ' : padChar.charAt(0);
