    public static byte convertHexDigit(byte b) {
        if ((b >= '0') && (b <= '9'))
            return (byte) (b - '0');
        if ((b >= 'a') && (b <= 'f'))
            return (byte) (b - 'a' + 10);
        if ((b >= 'A') && (b <= 'F'))
            return (byte) (b - 'A' + 10);
        throw new IllegalArgumentException("!hex:" + Integer.toHexString(0xff & b));
    }

    /* ------------------------------------------------------------ */
    public static void toHex(byte b, Appendable buf) {
        try {
            int bi = 0xff & b;
            int c = '0' + (bi / 16) % 16;
            if (c > '9')
                c = 'A' + (c - '0' - 10);
            buf.append((char) c);
            c = '0' + bi % 16;
            if (c > '9')
                c = 'A' + (c - '0' - 10);
            buf.append((char) c);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

