    public static boolean removeCookie(String cookieName) {
        HttpServletResponse httpResponse = HttpParameters.localInvoker().getHttpResponse();
        Cookie cookie = new Cookie(cookieName, "");
        cookie.setMaxAge(0);
        httpResponse.addCookie(cookie);
        return true;
    }
