        final int bufferEnd = totalBytesRetired + bufferSize;
        if (bufferEnd > currentLimit)
        {
            // Limit is in current buffer.
            bufferSizeAfterLimit = bufferEnd - currentLimit;
            bufferSize -= bufferSizeAfterLimit;
        }
        else
