        if(map.containsKey(val)) {
            map.remove(val);
            values.remove(values.indexOf(val));
            return true;
        }
        return false;
    }

    /** Get a random element from the set. */
    public int getRandom() {
        int random = (int)(Math.random() * values.size());
        int valueToReturn = values.get(random);
