    /**
     * Read a {@code double} field value from the stream.
     */
    @Override
    public double readDouble() throws IOException
    {
        checkIfPackedField();
        return Double.longBitsToDouble(readRawLittleEndian64());
    }

    /**
     * Read a {@code float} field value from the stream.
     */
    @Override
    public float readFloat() throws IOException
    {
        checkIfPackedField();
        return Float.intBitsToFloat(readRawLittleEndian32());
    }

    /**
     * Read a {@code uint64} field value from the stream.
     */
    @Override
    public long readUInt64() throws IOException
    {
        checkIfPackedField();
        return readRawVarint64();
    }

    /**
     * Read an {@code int64} field value from the stream.
     */
    @Override
    public long readInt64() throws IOException
    {
        checkIfPackedField();
        return readRawVarint64();
    }

    /**
     * Read an {@code int32} field value from the stream.
     */
    @Override
    public int readInt32() throws IOException
    {
        checkIfPackedField();
        return readRawVarint32();
    }

    /**
     * Read a {@code fixed64} field value from the stream.
     */
    @Override
    public long readFixed64() throws IOException
    {
        checkIfPackedField();
        return readRawLittleEndian64();
    }

    /**
     * Read a {@code fixed32} field value from the stream.
     */
    @Override
    public int readFixed32() throws IOException
    {
        checkIfPackedField();
        return readRawLittleEndian32();
    }

    /**
     * Read a {@code bool} field value from the stream.
     */
    @Override
    public boolean readBool() throws IOException
    {
        checkIfPackedField();
        return readRawVarint32() != 0;
    }

    /**
     * Read a {@code string} field value from the stream.
     */
    @Override
    public String readString() throws IOException
    {
        final int size = readRawVarint32();
        if (size <= (bufferSize - bufferPos) && size > 0)
        {
            // Fast path: We already have the bytes in a contiguous buffer, so
            // just copy directly from it.
            final String result = STRING.deser(buffer, bufferPos, size);
            bufferPos += size;
            return result;
        }
        else
        {
            // Slow path: Build a byte array first then copy it.
            return STRING.deser(readRawBytes(size));
        }
    }

    /**
     * Read a {@code string} field value from the stream into a ByteBuffer.
     */
    @Override
    public void readBytes(final ByteBuffer bb) throws IOException
    {
        final int size = readRawVarint32();

        if (size <= (bufferSize - bufferPos) && size > 0)
        {
            // Fast path: We already have the bytes in a contiguous buffer, so
            // just copy directly from it.
            bb.limit(size);
            bb.put(buffer, bufferPos, size);
            bufferPos += size;
        }
        else
        {
            // Slow path: Build a byte array first then copy it.
            bb.put(readRawBytes(size));
        }
    }

    @Override
    public <T> T mergeObject(T value, final Schema<T> schema) throws IOException
    {
        if (decodeNestedMessageAsGroup)
            return mergeObjectEncodedAsGroup(value, schema);

        final int length = readRawVarint32();
        // if (recursionDepth >= recursionLimit) {
        // throw ProtobufException.recursionLimitExceeded();
        // }
        final int oldLimit = pushLimit(length);
        // ++recursionDepth;

        if (value == null)
        {
            value = schema.newMessage();
        }
        schema.mergeFrom(this, value);
        if (!schema.isInitialized(value))
        {
            throw new UninitializedMessageException(value, schema);
        }
        checkLastTagWas(0);
        // --recursionDepth;
        popLimit(oldLimit);
        return value;
    }

    /**
     * Reads a message field value from the stream (using the {@code group} encoding).
     */
    private <T> T mergeObjectEncodedAsGroup(T value, final Schema<T> schema) throws IOException
    {
        // if (recursionDepth >= recursionLimit) {
        // throw ProtobufException.recursionLimitExceeded();
        // }
        // ++recursionDepth;

        if (value == null)
        {
            value = schema.newMessage();
        }
        schema.mergeFrom(this, value);
        if (!schema.isInitialized(value))
        {
            throw new UninitializedMessageException(value, schema);
        }
        // handling is in #readFieldNumber
        checkLastTagWas(0);
        // --recursionDepth;
        return value;
    }

