    /**
     * Returns the {@link Type} values corresponding to the argument types of the given method.
     *
     * @param method a method.
     * @return the {@link Type} values corresponding to the argument types of the given method.
     */
    public static Type[] getArgumentTypes(final Method method) {
        Class<?>[] classes = method.getParameterTypes();
        Type[] types = new Type[classes.length];
        for (int i = classes.length - 1; i >= 0; --i) {
            types[i] = getType(classes[i]);
        }
        return types;
    }

    /**
     * Returns the return type of methods of this type. This method should only be used for method
     * types.
     *
     * @return the return type of methods of this type.
     */
    public Type getReturnType() {
        return getReturnType(getDescriptor());
    }

    /**
     * Returns the {@link Type} corresponding to the return type of the given method descriptor.
     *
     * @param methodDescriptor a method descriptor.
     * @return the {@link Type} corresponding to the return type of the given method descriptor.
     */
    public static Type getReturnType(final String methodDescriptor) {
        return getTypeInternal(methodDescriptor, getReturnTypeOffset(methodDescriptor), methodDescriptor.length());
    }

    /**
     * Returns the {@link Type} corresponding to the return type of the given method.
     *
     * @param method a method.
     * @return the {@link Type} corresponding to the return type of the given method.
     */
    public static Type getReturnType(final Method method) {
        return getType(method.getReturnType());
    }

    /**
     * Returns the start index of the return type of the given method descriptor.
     *
     * @param methodDescriptor a method descriptor.
     * @return the start index of the return type of the given method descriptor.
     */
    static int getReturnTypeOffset(final String methodDescriptor) {
        // Skip the first character, which is always a '('.
        int currentOffset = 1;
        // Skip the argument types, one at a each loop iteration.
        while (methodDescriptor.charAt(currentOffset) != ')') {
            while (methodDescriptor.charAt(currentOffset) == '[') {
                currentOffset++;
            }
            if (methodDescriptor.charAt(currentOffset++) == 'L') {
                // Skip the argument descriptor content.
                int semiColumnOffset = methodDescriptor.indexOf(';', currentOffset);
                currentOffset = Math.max(currentOffset, semiColumnOffset + 1);
            }
        }
        return currentOffset + 1;
    }

    /**
     * Returns the {@link Type} corresponding to the given field or method descriptor.
     *
     * @param descriptorBuffer a buffer containing the field or method descriptor.
     * @param descriptorBegin the beginning index, inclusive, of the field or method descriptor in
     *     descriptorBuffer.
     * @param descriptorEnd the end index, exclusive, of the field or method descriptor in
     *     descriptorBuffer.
     * @return the {@link Type} corresponding to the given type descriptor.
     */
    private static Type getTypeInternal(final String descriptorBuffer, final int descriptorBegin, final int descriptorEnd) {
        switch (descriptorBuffer.charAt(descriptorBegin)) {
        case 'V':
            return VOID_TYPE;
        case 'Z':
            return BOOLEAN_TYPE;
        case 'C':
            return CHAR_TYPE;
        case 'B':
            return BYTE_TYPE;
        case 'S':
            return SHORT_TYPE;
        case 'I':
            return INT_TYPE;
        case 'F':
            return FLOAT_TYPE;
        case 'J':
            return LONG_TYPE;
        case 'D':
            return DOUBLE_TYPE;
        case '[':
            return new Type(ARRAY, descriptorBuffer, descriptorBegin, descriptorEnd);
        case 'L':
            return new Type(OBJECT, descriptorBuffer, descriptorBegin + 1, descriptorEnd - 1);
        case '(':
            return new Type(METHOD, descriptorBuffer, descriptorBegin, descriptorEnd);
        default:
            throw new IllegalArgumentException();
        }
    }
