    /**
     * Returns the sort of this type.
     *
     * @return {@link #VOID}, {@link #BOOLEAN}, {@link #CHAR}, {@link #BYTE}, {@link #SHORT}, {@link
     *     #INT}, {@link #FLOAT}, {@link #LONG}, {@link #DOUBLE}, {@link #ARRAY}, {@link #OBJECT} or
     *     {@link #METHOD}.
     */
    public int getSort() {
        return sort == INTERNAL ? OBJECT : sort;
    }

