    	CharSequence result = clean((CharSequence) str);

        return result!=null?result.toString():null;
    }

    public static CharSequence clean(CharSequence str) {
        str = trimWhitespace(str);
        if (!hasLength(str)) {
            return null;
        }
        return str;
