    static final int DEFAULT_SIZE_LIMIT = 64 << 20; // 64MB
    static final int DEFAULT_BUFFER_SIZE = 4096;

    public CodedInput(final byte[] buffer, final int off, final int len,
            boolean decodeNestedMessageAsGroup)
